def _decode(desc: list[Any], value: Any) -> Any:
    if desc[0] == "nullable":
        return None if value is None else _decode(desc[1], value)
    if value is None:
        raise TypeError("null is not allowed")
    if desc[0] == "model":
        return _MODEL_TYPES[desc[1]].from_dict(value)
    if desc[0] == "tuple":
        if not isinstance(value, (list, tuple)):
            raise TypeError("expected an array")
        return tuple(_decode(desc[1], item) for item in value)
    if desc[0] == "mapping":
        if not isinstance(value, Mapping):
            raise TypeError("expected an object")
        return _freeze(value)
    expected = {"str": str, "int": int, "float": (int, float), "bool": bool, "Any": object}[desc[1]]
    if not isinstance(value, expected) or (desc[1] in {"int", "float"} and isinstance(value, bool)):
        raise TypeError(f"expected {desc[1]}")
    return float(value) if desc[1] == "float" else value


def _validate(value: WireModel) -> None:
    spec = _MODEL_SPECS[value.__class__.__name__]
    for name, constraints in spec.items():
        item = getattr(value, name)
        if item is None:
            if constraints["required"] and not constraints["nullable"]:
                raise ValueError(f"{name} may not be null")
            continue
        _assert_type(constraints["descriptor"], item, name)
        if constraints["hasConst"] and item != constraints["const"]:
            raise ValueError(f"{name} must equal {constraints['const']!r}")
        enum = constraints["enum"]
        if enum is not None and item not in enum:
            raise ValueError(f"{name} must be one of {enum!r}")
        minimum = constraints["minimum"]
        maximum = constraints["maximum"]
        if minimum is not None and item < minimum:
            raise ValueError(f"{name} is below its minimum")
        if maximum is not None and item > maximum:
            raise ValueError(f"{name} exceeds its maximum")
        min_items = constraints["minItems"]
        max_items = constraints["maxItems"]
        if min_items is not None and len(item) < min_items:
            raise ValueError(f"{name} has too few items")
        if max_items is not None and len(item) > max_items:
            raise ValueError(f"{name} has too many items")
        min_length = constraints["minLength"]
        if min_length is not None and len(item) < min_length:
            raise ValueError(f"{name} is too short")
        pattern = constraints["pattern"]
        if pattern is not None and re.fullmatch(pattern, item) is None:
            raise ValueError(f"{name} does not match its pattern")
        if constraints["uniqueItems"] and any(item[index] in item[:index] for index in range(len(item))):
            raise ValueError(f"{name} must contain unique items")
        exclusive_minimum = constraints["exclusiveMinimum"]
        if exclusive_minimum is not None and item <= exclusive_minimum:
            raise ValueError(f"{name} must be greater than its exclusive minimum")
    variant = _VARIANT_SPECS.get(value.__class__.__name__)
    if variant is not None:
        discriminator = getattr(value, variant["discriminator"])
        required = set(variant["variants"].get(discriminator, ()))
        if not required:
            raise ValueError(f"unknown {variant['discriminator']} variant {discriminator!r}")
        variant_fields = set().union(*map(set, variant["variants"].values()))
        missing = sorted(name for name in required if getattr(value, name) is None and not _MODEL_SPECS[value.__class__.__name__][name]["nullable"])
        forbidden = sorted(name for name in variant_fields - required if getattr(value, name) is not None)
        if missing or forbidden:
            raise ValueError(f"invalid {discriminator} variant fields; missing={missing!r}, forbidden={forbidden!r}")


def _assert_type(desc: list[Any], value: Any, path: str) -> None:
    if desc[0] == "nullable":
        if value is not None:
            _assert_type(desc[1], value, path)
        return
    if desc[0] == "model":
        if not isinstance(value, _MODEL_TYPES[desc[1]]):
            raise TypeError(f"{path} must be {desc[1]}")
        return
    if desc[0] == "tuple":
        if not isinstance(value, tuple):
            raise TypeError(f"{path} must be an immutable tuple")
        for index, item in enumerate(value):
            _assert_type(desc[1], item, f"{path}[{index}]")
        return
    if desc[0] == "mapping":
        if not isinstance(value, Mapping):
            raise TypeError(f"{path} must be a mapping")
        return
    expected = {"str": str, "int": int, "float": (int, float), "bool": bool, "Any": object}[desc[1]]
    if not isinstance(value, expected) or (desc[1] in {"int", "float"} and isinstance(value, bool)):
        raise TypeError(f"{path} must be {desc[1]}")


def to_wire(value: Any) -> Any:
    """Convert generated immutable models into JSON-compatible values."""
    return _wire(value)
